import{_ as a,o as r,c as o,a2 as t}from"./chunks/framework.B2_yzPFF.js";const b=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":null}'),i={name:"changelog.md"};function d(s,e,l,n,c,h){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to <code>@mshindi-labs/refetch</code> are documented here.</p><h2 id="_3-3-0-2026-11-06" tabindex="-1"><a href="https://github.com/mshindi-labs/refetch/compare/v3.2.0...v3.3.0" target="_blank" rel="noreferrer">3.3.0</a> (2026-11-06) <a class="header-anchor" href="#_3-3-0-2026-11-06" aria-label="Permalink to &quot;[3.3.0](https://github.com/mshindi-labs/refetch/compare/v3.2.0...v3.3.0) (2026-11-06)&quot;">​</a></h2><h3 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><strong>interceptors:</strong> attach the resolved request to responses and allow short-circuits (<a href="https://github.com/mshindi-labs/refetch/commit/5bc52f564b3a0f72b7def3e5e18f4756814a1a85" target="_blank" rel="noreferrer">5bc52f5</a>)</li><li><strong>interceptors:</strong> attach the resolved request to responses and allow short-circuits (<a href="https://github.com/mshindi-labs/refetch/commit/da162914911e03cd8848e6d07201dfb9c5e24572" target="_blank" rel="noreferrer">da16291</a>), closes <a href="https://github.com/mshindi-labs/refetch/issues/20" target="_blank" rel="noreferrer">#20</a></li></ul><h3 id="bug-fixes" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li><strong>interceptors:</strong> redact credential headers in the response.request snapshot (<a href="https://github.com/mshindi-labs/refetch/commit/50b17177957c46c91f4a8c3c3bb1380a6cc9b55c" target="_blank" rel="noreferrer">50b1717</a>), closes <a href="https://github.com/mshindi-labs/refetch/issues/20" target="_blank" rel="noreferrer">#20</a></li></ul><h2 id="_3-2-0-2026-10-20" tabindex="-1"><a href="https://github.com/mshindi-labs/refetch/compare/v3.1.2...v3.2.0" target="_blank" rel="noreferrer">3.2.0</a> (2026-10-20) <a class="header-anchor" href="#_3-2-0-2026-10-20" aria-label="Permalink to &quot;[3.2.0](https://github.com/mshindi-labs/refetch/compare/v3.1.2...v3.2.0) (2026-10-20)&quot;">​</a></h2><h3 id="features-1" tabindex="-1">Features <a class="header-anchor" href="#features-1" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><strong>retry:</strong> honour Retry-After, add back-off strategies, jitter, method and status allow-lists (<a href="https://github.com/mshindi-labs/refetch/issues/42" target="_blank" rel="noreferrer">#42</a>) (<a href="https://github.com/mshindi-labs/refetch/commit/73924c61a618f87e7a06c6aba6eb08f497cda501" target="_blank" rel="noreferrer">73924c6</a>), closes <a href="https://github.com/mshindi-labs/refetch/issues/11" target="_blank" rel="noreferrer">#11</a></li></ul><h2 id="_3-1-2-2026-10-20" tabindex="-1"><a href="https://github.com/mshindi-labs/refetch/compare/v3.1.1...v3.1.2" target="_blank" rel="noreferrer">3.1.2</a> (2026-10-20) <a class="header-anchor" href="#_3-1-2-2026-10-20" aria-label="Permalink to &quot;[3.1.2](https://github.com/mshindi-labs/refetch/compare/v3.1.1...v3.1.2) (2026-10-20)&quot;">​</a></h2><h3 id="bug-fixes-1" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-1" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>keep Headers-shaped request headers in middleware and serialise query params safely (<a href="https://github.com/mshindi-labs/refetch/issues/40" target="_blank" rel="noreferrer">#40</a>) (<a href="https://github.com/mshindi-labs/refetch/commit/f03e4f63d8d4f97dce2505dc69046d7343396cff" target="_blank" rel="noreferrer">f03e4f6</a>)</li></ul><h2 id="_3-1-1-2026-10-20" tabindex="-1"><a href="https://github.com/mshindi-labs/refetch/compare/v3.1.0...v3.1.1" target="_blank" rel="noreferrer">3.1.1</a> (2026-10-20) <a class="header-anchor" href="#_3-1-1-2026-10-20" aria-label="Permalink to &quot;[3.1.1](https://github.com/mshindi-labs/refetch/compare/v3.1.0...v3.1.1) (2026-10-20)&quot;">​</a></h2><h3 id="bug-fixes-2" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-2" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>report parse failures, never throw from interceptors, send stream bodies with duplex (<a href="https://github.com/mshindi-labs/refetch/commit/4a4cffb5a4ef3bb983bb9887c7947c957d18a695" target="_blank" rel="noreferrer">4a4cffb</a>)</li><li>report parse failures, never throw from interceptors, send stream bodies with duplex (<a href="https://github.com/mshindi-labs/refetch/commit/05bf41cc3765d752421dbd71e151592a552a3e90" target="_blank" rel="noreferrer">05bf41c</a>), closes <a href="https://github.com/mshindi-labs/refetch/issues/5" target="_blank" rel="noreferrer">#5</a> <a href="https://github.com/mshindi-labs/refetch/issues/6" target="_blank" rel="noreferrer">#6</a> <a href="https://github.com/mshindi-labs/refetch/issues/7" target="_blank" rel="noreferrer">#7</a></li></ul><h2 id="_3-1-0-2026-10-20" tabindex="-1"><a href="https://github.com/mshindi-labs/refetch/compare/v3.0.0...v3.1.0" target="_blank" rel="noreferrer">3.1.0</a> (2026-10-20) <a class="header-anchor" href="#_3-1-0-2026-10-20" aria-label="Permalink to &quot;[3.1.0](https://github.com/mshindi-labs/refetch/compare/v3.0.0...v3.1.0) (2026-10-20)&quot;">​</a></h2><h3 id="bug-fixes-3" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-3" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li><strong>fetch:</strong> typed timeout/transport errors, honoured cancellation, body-read timeout (<a href="https://github.com/mshindi-labs/refetch/commit/1db8251f788970f4c9adc4af46dbaf88201add2a" target="_blank" rel="noreferrer">1db8251</a>)</li><li><strong>fetch:</strong> typed timeout/transport errors, honoured cancellation, body-read timeout (<a href="https://github.com/mshindi-labs/refetch/commit/c70bff53ce7add02309cdbb3c4706a781460e4e7" target="_blank" rel="noreferrer">c70bff5</a>), closes <a href="https://github.com/mshindi-labs/refetch/issues/2" target="_blank" rel="noreferrer">#2</a> <a href="https://github.com/mshindi-labs/refetch/issues/3" target="_blank" rel="noreferrer">#3</a> <a href="https://github.com/mshindi-labs/refetch/issues/4" target="_blank" rel="noreferrer">#4</a> <a href="https://github.com/mshindi-labs/refetch/issues/10" target="_blank" rel="noreferrer">#10</a></li><li><strong>package:</strong> resolve CJS types, add sideEffects and metadata, raise engines (<a href="https://github.com/mshindi-labs/refetch/commit/62019f73a02e7c69bba4fe701a7db6da50c08dcb" target="_blank" rel="noreferrer">62019f7</a>)</li><li><strong>package:</strong> resolve CJS types, add sideEffects and metadata, raise engines (<a href="https://github.com/mshindi-labs/refetch/commit/e9b59ef7e4bf950f7559590986edcad269a98f1a" target="_blank" rel="noreferrer">e9b59ef</a>), closes <a href="https://github.com/mshindi-labs/refetch/issues/14" target="_blank" rel="noreferrer">#14</a></li></ul><h3 id="continuous-integration" tabindex="-1">Continuous Integration <a class="header-anchor" href="#continuous-integration" aria-label="Permalink to &quot;Continuous Integration&quot;">​</a></h3><ul><li><strong>release:</strong> automate versioning, changelog and npm publishing with release-please (<a href="https://github.com/mshindi-labs/refetch/commit/b88f3be9497ee7c80a059bdc1883e6abea7588fb" target="_blank" rel="noreferrer">b88f3be</a>), closes <a href="https://github.com/mshindi-labs/refetch/issues/33" target="_blank" rel="noreferrer">#33</a></li></ul><h2 id="_3-0-0-—-2026-04-22" tabindex="-1">[3.0.0] — 2026-04-22 <a class="header-anchor" href="#_3-0-0-—-2026-04-22" aria-label="Permalink to &quot;[3.0.0] — 2026-04-22&quot;">​</a></h2><p>Full architectural redesign. Pure functional TypeScript, 14 single-responsibility modules, zero runtime dependencies.</p><h3 id="breaking-changes" tabindex="-1">Breaking Changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking Changes&quot;">​</a></h3><ul><li><code>Content-Type</code> removed from <code>DEFAULT_HEADERS</code> — set per-request via <code>getBodyContentType()</code> instead</li><li><code>post</code>/<code>put</code>/<code>patch</code> body type is now the <strong>second</strong> generic parameter: <code>post&lt;TResponse, TBody&gt;</code></li><li><code>addRequestTransform</code> / <code>addResponseTransform</code> deprecated in favour of the interceptor API</li><li><code>utils.ts</code> dissolved — its exports moved into six focused modules (<code>url.ts</code>, <code>headers.ts</code>, <code>body.ts</code>, <code>response.ts</code>, <code>fetch.ts</code>, <code>errors.ts</code>)</li></ul><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Interceptor system</strong> — axios-style request/response middleware with Map-based storage, auto-increment IDs, and <code>eject(id)</code> / <code>clear()</code>. Request interceptors run LIFO; response interceptors run FIFO per retry attempt.</li><li><strong><code>RefetchError</code> discriminated union</strong> — per-kind fields (<code>http</code>, <code>timeout</code>, <code>cancel</code>, <code>network</code>, <code>parse</code>, <code>unknown</code>) alongside <code>PROBLEM_CODE</code></li><li><strong>Retry</strong> — <code>RetryConfig</code> per-request or instance-wide; shorthand number form; request interceptors run once before the retry loop</li><li><strong><code>stream()</code></strong> — returns <code>ApiResponse&lt;ReadableStream&lt;T&gt;&gt;</code> with no body parsing and no retry</li><li><strong><code>pipe()</code> + middleware HOFs</strong> — <code>withAuth</code>, <code>withTimeout</code>, <code>withHeaders</code>, <code>withBaseURL</code>, <code>withLogging</code> compose onto instances without mutation</li><li><strong>Sub-path exports</strong> — <code>@mshindi-labs/refetch/retry</code>, <code>/middleware</code>, <code>/pipe</code> (tree-shakeable)</li><li><strong>Richer response body parsing</strong> — <code>+json</code> suffix MIME variants, <code>application/x-www-form-urlencoded</code> → <code>Record&lt;string,string&gt;</code>, binary MIME types → <code>Blob</code>, empty-body guard for 204/304/<code>content-length: 0</code></li><li><code>CancelError</code> and <code>createCancelToken</code> for explicit request cancellation</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><code>buildRefetchError</code> moved to <code>errors.ts</code>; <code>RefetchError</code> type defined in <code>types.ts</code></li><li>FormData <code>Content-Type</code> is always deleted so the browser can set the multipart boundary</li><li>README, CLAUDE.md, and CONTRIBUTING.md fully rewritten for v3</li></ul><hr><h2 id="_2-0-10-—-2025-11-02" tabindex="-1">[2.0.10] — 2025-11-02 <a class="header-anchor" href="#_2-0-10-—-2025-11-02" aria-label="Permalink to &quot;[2.0.10] — 2025-11-02&quot;">​</a></h2><p>Patch release — internal version bump, no API changes.</p><hr><h2 id="_2-0-9-—-2025-11-02" tabindex="-1">[2.0.9] — 2025-11-02 <a class="header-anchor" href="#_2-0-9-—-2025-11-02" aria-label="Permalink to &quot;[2.0.9] — 2025-11-02&quot;">​</a></h2><p>Patch release — internal version bump, no API changes.</p><hr><h2 id="_2-0-8-—-2025-11-02" tabindex="-1">[2.0.8] — 2025-11-02 <a class="header-anchor" href="#_2-0-8-—-2025-11-02" aria-label="Permalink to &quot;[2.0.8] — 2025-11-02&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>GitHub Actions publishing workflow</li></ul><hr><h2 id="_2-0-7-—-2025-11-01" tabindex="-1">[2.0.7] — 2025-11-01 <a class="header-anchor" href="#_2-0-7-—-2025-11-01" aria-label="Permalink to &quot;[2.0.7] — 2025-11-01&quot;">​</a></h2><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Config spread overriding merged headers — moved <code>...config</code> spread to the start of <code>fetchConfig</code> so explicitly merged headers always take precedence. Fixes JSON <code>POST</code> requests losing <code>Content-Type: application/json</code>.</li></ul><hr><h2 id="_2-0-6-—-2025-11-01" tabindex="-1">[2.0.6] — 2025-11-01 <a class="header-anchor" href="#_2-0-6-—-2025-11-01" aria-label="Permalink to &quot;[2.0.6] — 2025-11-01&quot;">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Exported <code>headersToObject</code>, <code>classifyProblem</code>, and <code>buildQueryString</code> utility functions</li></ul><hr><h2 id="_2-0-5-—-2025-11-01" tabindex="-1">[2.0.5] — 2025-11-01 <a class="header-anchor" href="#_2-0-5-—-2025-11-01" aria-label="Permalink to &quot;[2.0.5] — 2025-11-01&quot;">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Exported internal utilities: <code>buildUrl</code>, <code>mergeHeaders</code>, <code>fetchWithTimeout</code>, <code>parseResponseBody</code>, <code>normalizeSuccessResponse</code>, <code>normalizeErrorResponse</code>, <code>prepareRequestBody</code>, <code>shouldHaveBody</code></li></ul><hr><h2 id="_2-0-4-—-2025-11-01" tabindex="-1">[2.0.4] — 2025-11-01 <a class="header-anchor" href="#_2-0-4-—-2025-11-01" aria-label="Permalink to &quot;[2.0.4] — 2025-11-01&quot;">​</a></h2><p>Patch release — internal version bump, no API changes.</p><hr><h2 id="_2-0-3-—-2025-10-30" tabindex="-1">[2.0.3] — 2025-10-30 <a class="header-anchor" href="#_2-0-3-—-2025-10-30" aria-label="Permalink to &quot;[2.0.3] — 2025-10-30&quot;">​</a></h2><h3 id="breaking-changes-1" tabindex="-1">Breaking Changes <a class="header-anchor" href="#breaking-changes-1" aria-label="Permalink to &quot;Breaking Changes&quot;">​</a></h3><ul><li>Removed <code>PROBLEM_CODES</code> constant — use the <code>PROBLEM_CODE</code> enum directly</li></ul><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><code>DEFAULT_HEADERS</code> no longer applied to <code>FormData</code> and <code>URLSearchParams</code> — fixes multipart/form-data being overridden</li><li>Inconsistent error response handling — all error paths now use <code>normalizeErrorResponse()</code> uniformly</li></ul><h3 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><code>LINK</code> and <code>UNLINK</code> HTTP methods</li><li><code>any(method, url, data?, config?)</code> for custom HTTP verbs (e.g. <code>PROPFIND</code>, <code>MKCOL</code>)</li><li><code>getBaseURL()</code> for base URL introspection</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Extracted duplicate query parameter logic into <code>buildQueryString()</code> helper (~30 lines removed)</li><li>Simplified header management by normalising to the <code>Headers</code> class — <code>setHeader</code> and <code>deleteHeader</code> each reduced from ~12–19 lines to 3</li><li>Removed unused <code>ERROR_MESSAGES</code> constants</li><li>Enabled minification in tsup — bundle size ~2.3 KB gzipped (40% smaller than v2.0.2)</li></ul><hr><h2 id="_2-0-2-—-2025-10-30" tabindex="-1">[2.0.2] — 2025-10-30 <a class="header-anchor" href="#_2-0-2-—-2025-10-30" aria-label="Permalink to &quot;[2.0.2] — 2025-10-30&quot;">​</a></h2><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>README import paths corrected to match published package structure</li></ul><hr><h2 id="_2-0-0-—-2025-10-30" tabindex="-1">[2.0.0] — 2025-10-30 <a class="header-anchor" href="#_2-0-0-—-2025-10-30" aria-label="Permalink to &quot;[2.0.0] — 2025-10-30&quot;">​</a></h2><h3 id="breaking-changes-2" tabindex="-1">Breaking Changes <a class="header-anchor" href="#breaking-changes-2" aria-label="Permalink to &quot;Breaking Changes&quot;">​</a></h3><ul><li>All <code>any</code> types replaced with <code>unknown</code> — consumers must provide explicit type parameters or assertions</li><li><code>api.config</code> is now readonly — use instance methods (<code>setBaseURL</code>, etc.) instead of direct mutation</li></ul><h3 id="fixed-3" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-3" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Memory leak in <code>fetchWithTimeout</code> — <code>AbortController</code> event listeners now cleaned up in <code>finally</code> block</li></ul><h3 id="added-5" tabindex="-1">Added <a class="header-anchor" href="#added-5" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><code>removeRequestTransform(fn)</code> / <code>removeResponseTransform(fn)</code> / <code>removeMonitor(fn)</code></li><li><code>clearRequestTransforms()</code> / <code>clearResponseTransforms()</code> / <code>clearMonitors()</code></li><li><code>isOkResponse&lt;T&gt;()</code> and <code>isErrorResponse&lt;T&gt;()</code> type guard exports</li><li>Input validation: transforms and monitors must be functions; URLs validated in <code>buildUrl</code></li><li>Absolute URL support (bypasses <code>baseURL</code> prepending)</li><li>Improved error messages include HTTP method and full URL for easier debugging</li><li><code>CONTRIBUTING.md</code></li></ul><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><code>RefetchConfig</code> now extends <code>Omit&lt;RequestInit, &#39;method&#39; | &#39;body&#39;&gt;</code> instead of <code>[key: string]: any</code></li><li>URL builder normalises trailing/leading slashes and prevents double slashes</li></ul><hr><h2 id="_1-0-0-—-2025-10-30" tabindex="-1">[1.0.0] — 2025-10-30 <a class="header-anchor" href="#_1-0-0-—-2025-10-30" aria-label="Permalink to &quot;[1.0.0] — 2025-10-30&quot;">​</a></h2><p>Initial release. Lightweight, apisauce-inspired HTTP client built on the native <code>fetch</code> API.</p><h3 id="features-2" tabindex="-1">Features <a class="header-anchor" href="#features-2" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Native <code>fetch</code> wrapper with standardised <code>ApiResponse&lt;T&gt;</code> format</li><li>Request/response transforms (sync and async)</li><li>Response monitors for logging and analytics</li><li>Timeout support via <code>AbortController</code></li><li><code>PROBLEM_CODE</code> enum for error classification</li><li>Full TypeScript support with generics</li><li>Dual package output (ESM + CommonJS)</li></ul>',83)])])}const f=a(i,[["render",d]]);export{b as __pageData,f as default};
